            svc.create("Task", due_at=datetime(2025, 12, 1))

    def test_due_at_converted_to_utc(self, svc):
        eastern = timezone(timedelta(hours=-5))
        due = datetime(2025, 12, 1, 10, 0, tzinfo=eastern)
        task = svc.create("Task", due_at=due)
        assert task.due_at.tzinfo == timezone.utc

    def test_tags_normalized_and_deduped(self, svc):
        task = svc.create("Task", tags=["Foo", "foo", "bar"])
        names = [t.name for t in task.tags]
        assert names == ["foo", "bar"]


